insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'gap_ela_v1'
from (values
('110.2.b.10.A',1,'Before writing about your pet, what can you do first to get ideas?','["talk about it and draw a picture", "erase the paper", "close the book", "throw away the pencil"]'::jsonb,0,'Ideas come from talking and drawing.','original'),
('110.2.b.10.B',1,'You draw three pictures to tell a story about a picnic. What should you do next to organize your ideas?','["paint the table", "put the pictures in order", "hide the pictures", "cut the paper into bits"]'::jsonb,1,'Order shows what happens first, next, last.','original'),
('110.2.b.10.D.ix',1,'Which spelling of the little word that often comes before a noun, like "__ cat," is correct?','["thu", "thee", "the", "tha"]'::jsonb,2,'The is a common word to know by sight.','original'),
('110.2.b.10.D.ix',1,'Which spelling of the word that tells what someone spoke, like "She __ hello," is correct?','["sed", "sad", "sayd", "said"]'::jsonb,3,'Said is a high-frequency word.','original'),
('110.2.b.6.B',1,'After you hear a story about a bear, which is a good way to show you understood it?','["draw the bear and tell what happened", "cover your ears", "walk away", "sing a different song"]'::jsonb,0,'A drawing and a retelling show understanding.','original'),
('110.2.b.6.E',1,'A good way to remember a new story is to...','["tear the book", "draw a picture of your favorite part", "forget the pictures", "hide the pages"]'::jsonb,1,'Illustrating helps you interact with the story.','original'),
('110.2.b.6.F',1,'Your teacher teaches you the new word "enormous." Which sentence uses it?','["The ant is enormous and tiny.", "Enormous is a red dog.", "The elephant is enormous.", "I enormous the book."]'::jsonb,2,'It means very big.','original'),
('110.2.b.11.A',1,'A personal narrative tells about...','["a recipe card", "a made-up dragon only", "a list of numbers", "something that happened to you"]'::jsonb,3,'Personal means about you.','original'),
('110.2.b.11.B',1,'Which sentence could be in an informational text about frogs?','["Frogs lay eggs in water.", "My sock is lost.", "Once upon a time, a princess slept.", "Hooray for cake!"]'::jsonb,0,'It gives true facts.','original'),
('110.3.b.11.A',2,'Which idea could you draw or brainstorm before writing about a trip to the park?','["rain boots on a shelf", "swings, slide, and picnic", "math facts", "a spelling test"]'::jsonb,1,'Ideas that fit the topic.','original'),
('110.3.b.2.C.ii',2,'Which spelling is right for the word a red sign tells drivers to do?','["stopp", "stope", "stop", "stap"]'::jsonb,2,'Initial consonant blend st.','original'),
('110.3.b.2.C.ii',2,'Which spelling is right for a small piece of a potato or cookie?','["cip", "chipp", "shipp", "chip"]'::jsonb,3,'The digraph ch is at the start.','original'),
('110.3.b.2.C.ii',2,'Which spelling is right for what happens when you jump into a puddle?','["splash", "sblash", "splach", "spalsh"]'::jsonb,0,'The trigraph spl begins the word.','original'),
('110.3.b.2.C.iii',2,'Which spelling is right for water that falls from clouds?','["rayn", "rain", "rane", "rainn"]'::jsonb,1,'The ai vowel team spells long a.','original'),
('110.3.b.2.C.iii',2,'Which spelling is right for something that floats on a lake?','["boate", "bowt", "boat", "bote"]'::jsonb,2,'The oa vowel team spells long o.','original'),
('110.3.b.2.F',2,'When you print a sentence, what should you leave between words?','["a big drawing", "nothing", "a number", "a small space"]'::jsonb,3,'Spaces make words easy to read.','original'),
